  drillImpactTip: '"Hit the middle, own the yardage"',
  drillGateTitle: 'Path Gate Drill',
  drillGateDesc: 'Set two tees 1 inch wider than your clubhead, creating a path gate. Swing through without touching either tee. This ingrains a tighter swing path and reduces left-right dispersion from club path error.',
