  drillShaftTitle: 'Forward Shaft Lean at Impact',
  drillShaftDesc: 'Place a shaft in the ground angled forward from the ball. Practice impacts where your grip end matches the shaft angle. Forward lean de-lofts the club, bringing launch and spin to optimal levels.',
