  drillTempoTitle: '3:1 Tempo Drill',
  drillTempoDesc: 'Use a metronome app at 72 bpm. Backswing takes 3 beats, downswing 1. Inconsistent tempo is the hidden driver of variable contact - a measured beat forces the same delivery every time.',
  drillTempoTip: '"Slow back, explode through"',
  drillHalfTitle: 'Half-Swing Compression Drill',
  drillHalfDesc: 'Make swings stopping at waist height on the follow-through. Focus on solid contact and a feeling of trapping the ball against the ground. This builds the strike consistency habit before re-adding swing length.',
