  drillLowFaceTitle: 'Low-Face Strike Correction',
  drillLowFaceDesc: 'Tee the driver so at least half the ball sits above the crown. Rehearse brushing the top of the tee and track Vertical Impact on the monitor to confirm a center-to-slightly-high strike. Low strikes add backspin and kill launch - a center-high contact can drop spin by up to 1,000 rpm.',
  drillLowFaceTip: '"High on the face, high on the leaderboard"',
  drillWallTitle: 'Wall Drill - Stop Early Extension',
  drillWallDesc: 'Set up with your rear lightly touching a wall or sturdy chair. Make swings keeping your trail glute against the wall on the backswing, then feel your lead glute take over contact with the wall through impact. No wall room? Use a chair behind you or film your side-on to spot the hip thrust.',
  drillWallTip: '"Glutes to the wall, posture through the ball"',
  drillStepTitle: 'Step-Through Hip Drill',
  drillStepDesc: 'Hit mid-iron shots and let your trail foot step toward the target just after impact, finishing with your belt buckle pointing past the target line. Stalled hips force a hand-flip that spikes dynamic loft and costs distance - continuous rotation quiets the hands.',
  drillStepTip: '"Clear the hips, the hands go quiet"',
  drillLagTitle: 'Pump Drill - Build Lag',
  drillLagDesc: 'With a light grip, drag the handle to start the downswing so the clubhead lags behind your hands. Rehearse three pump moves stopping at hip height with the shaft still angled back toward the ball, then hit on the fourth rep. Preserving lag delivers hands-first impact and de-lofts the club.',
  drillLagTip: '"Drag the handle, snap it late"',
  drillHeadcoverTitle: 'Headcover Path Drill',
  drillHeadcoverDesc: 'Place a headcover or angled alignment stick just outside the target line and just behind the ball. An over-the-top move will strike it. Groove a downswing that drops the club to the inside and misses it. Out-to-in path with an open face is the root cause of the slice - rerouting inside shrinks face-to-path and flattens the spin axis.',
  drillHeadcoverTip: '"Drop it inside, swing to right field"',
  drillFaceCtrlTitle: 'Two-Knuckle Face Control',
  drillFaceCtrlDesc: 'Check that you see two knuckles of your lead hand at address. Hit half-swings feeling the face rotate to square through impact, then check Launch Direction and Club Face on the monitor. The face controls ~85% of start direction with driver - a single degree of face angle equals 7–12 yards offline at driver distance.',
  drillFaceCtrlTip: '"Square the face, start it on line"',
  drillLowPointTitle: 'Low-Point Line Drill',
  drillLowPointDesc: 'Spray a chalk line on the turf or place a folded towel 6 inches behind the ball. Train your divots to start on the target side of the line. Keep ~90% of weight on the lead side at impact. A low point behind the ball produces fat and thin shots; moving it forward ensures ball-first contact every time.',
  drillLowPointTip: '"Ball first, turf second"',
  drillConnTitle: 'Connection - Towel Under Arms',
  drillConnDesc: 'Tuck a small towel or glove under your lead armpit and make three-quarter swings, keeping it pinned through impact. When the arms disconnect from the body, swing plane and face angle vary shot to shot - pinning the towel forces arms and rotation to move as one unit.',
  drillConnTip: '"Arms and chest, one move"',
