  insightPathDetail: 'Una desviación de trayectoria de palo de {deg}° introduce dispersión lateral. Una trayectoria ≤2° mantiene la bola en línea. Afinar la trayectoria mejora tu zona de dispersión.',
  insightPathOpp: 'Objetivo ≤2°',
