  rcFixConsistency: 'Prioriza la consistencia de contacto antes de optimizar cualquier otra métrica.',
  drillShallowTitle: 'Reduce el ángulo de ataque',
  drillShallowDesc: 'Coloca una cubierta de cabeza a 15 cm detrás de la bola. Practica swings que no toquen la cubierta - esto fuerza una entrada más plana. El exceso de spin proviene de un ángulo de ataque empinado; aplanar 1,5° reduce el spin ~400–600 rpm y añade vuelo.',
  drillShallowTip: '"Roza la hierba, no caves"',
  drillImpactTitle: 'Ejercicio de zona de impacto',
  drillImpactDesc: 'Aplica spray de talco o una pegatina de impacto en la cara del palo. Golpea 10 bolas y lee el patrón de contacto. Un impacto descentrado te cuesta distancia - este ejercicio hace visible el problema para que puedas corregirlo.',
  drillImpactTip: '"Golpea el centro, gana la yarda"',
  drillGateTitle: 'Ejercicio de puerta de trayectoria',
  drillGateDesc: 'Coloca dos tees 2,5 cm más anchos que la cabeza de tu palo, creando una puerta de trayectoria. Pasa el swing sin tocar ningún tee. Esto afianza una trayectoria de swing más ajustada y reduce la dispersión lateral derivada del error de trayectoria de palo.',
  drillGateTip: '"El palo por la puerta, la bola por la línea"',
  drillShaftTitle: 'Inclinación del palo hacia delante en el impacto',
  drillShaftDesc: 'Clava un palo en el suelo inclinado hacia adelante desde la bola. Practica impactos en los que el extremo del grip coincida con el ángulo del palo. La inclinación hacia adelante reduce el loft, llevando el lanzamiento y el spin a niveles óptimos.',
  drillShaftTip: '"El mango manda, no sigue"',
  drillTempoTitle: 'Ejercicio de tempo 3:1',
  drillTempoDesc: 'Usa una app de metrónomo a 72 bpm. El backswing dura 3 tiempos, el downswing 1. El tempo inconsistente es la causa oculta del contacto variable: un ritmo medido fuerza la misma entrega cada vez.',
  drillTempoTip: '"Lento atrás, explota a través"',
  drillHalfTitle: 'Ejercicio de compresión a medio swing',
  drillHalfDesc: 'Haz swings parando a la altura de la cintura en el follow-through. Concéntrate en un contacto sólido y la sensación de atrapar la bola contra el suelo. Esto crea el hábito de consistencia antes de volver a añadir longitud de swing.',
  drillHalfTip: '"Comprime, no lances"',
  drillLowFaceTitle: 'Corrección de impacto en cara baja',
  drillLowFaceDesc: 'Pon el tee del driver de modo que al menos la mitad de la bola quede sobre la corona. Ensaya rozar la parte alta del tee y controla el Impacto Vertical en el monitor para confirmar un golpe de centro a ligeramente alto. Los golpes bajos añaden backspin y matan el lanzamiento: un contacto centro-alto puede reducir el spin hasta 1.000 rpm.',
  drillLowFaceTip: '"Alto en la cara, alto en la clasificación"',
  drillWallTitle: 'Ejercicio de pared - evita la extensión temprana',
  drillWallDesc: 'Colócate con la parte trasera tocando levemente una pared o silla firme. Haz swings manteniendo el glúteo trasero contra la pared en el backswing, y siente que el glúteo delantero toma el contacto con la pared en el impacto. ¿Sin pared? Usa una silla detrás o filma de perfil para detectar el empuje de cadera.',
  drillWallTip: '"Glúteos a la pared, postura a través de la bola"',
  drillStepTitle: 'Ejercicio de paso de cadera',
  drillStepDesc: 'Golpea hierros medios y deja que tu pie trasero dé un paso hacia el objetivo justo tras el impacto, terminando con la hebilla del cinturón apuntando más allá de la línea de objetivo. Las caderas bloqueadas fuerzan un giro de manos que dispara el loft dinámico y resta distancia - la rotación continua calma las manos.',
  drillStepTip: '"Libera las caderas y las manos se calman"',
  drillLagTitle: 'Ejercicio de bombeo - crea lag',
  drillLagDesc: 'Con un grip ligero, arrastra el mango para iniciar el downswing de modo que la cabeza del palo quede rezagada respecto a las manos. Ensaya tres movimientos de bombeo parando a la altura de la cadera con la varilla aún inclinada hacia la bola, y golpea en la cuarta repetición. Conservar el lag entrega un impacto con las manos primero y desloft el palo.',
  drillLagTip: '"Arrastra el mango, suéltalo tarde"',
  drillHeadcoverTitle: 'Ejercicio de trayectoria con cubrepalo',
  drillHeadcoverDesc: 'Coloca un cubrepalo o palo de alineación inclinado justo fuera de la línea del objetivo y detrás de la bola. Un movimiento por encima lo golpeará. Graba un downswing que deje caer el palo por dentro y lo evite. Una trayectoria de fuera a dentro con cara abierta es la causa del slice: reencaminar por dentro reduce el face-to-path y aplana el eje de giro.',
  drillHeadcoverTip: '"Déjalo caer por dentro, swing al campo derecho"',
  drillFaceCtrlTitle: 'Control de cara con dos nudillos',
  drillFaceCtrlDesc: 'Comprueba que ves dos nudillos de tu mano adelantada en la dirección. Haz medios swings sintiendo que la cara rota a cuadrada en el impacto, luego revisa Dirección de Lanzamiento y Cara del Palo en el monitor. La cara controla ~85% de la dirección de salida con driver: un grado de ángulo de cara equivale a 7–12 yardas fuera de línea a distancia de driver.',
  drillFaceCtrlTip: '"Cuadra la cara, sácala en línea"',
  drillLowPointTitle: 'Ejercicio de línea de punto bajo',
  drillLowPointDesc: 'Marca una línea de tiza en el césped o coloca una toalla doblada 15 cm detrás de la bola. Entrena tus divots para que empiecen en el lado del objetivo de la línea. Mantén ~90% del peso en el lado adelantado en el impacto. Un punto bajo detrás de la bola produce golpes gordos y finos; moverlo hacia delante asegura contacto bola-primero siempre.',
  drillLowPointTip: '"Primero la bola, luego el césped"',
  drillConnTitle: 'Conexión - toalla bajo los brazos',
  drillConnDesc: 'Coloca una toalla pequeña o un guante bajo la axila adelantada y haz swings de tres cuartos manteniéndola sujeta en el impacto. Cuando los brazos se desconectan del cuerpo, el plano de swing y el ángulo de cara varían de tiro a tiro: sujetar la toalla fuerza a brazos y rotación a moverse como una unidad.',
  drillConnTip: '"Brazos y pecho, un solo movimiento"',
