  rcFixConsistency: 'Priorisiere Kontaktkonstanz, bevor du andere Kennzahlen optimierst.',
  drillShallowTitle: 'Anstellwinkel flacher machen',
  drillShallowDesc: 'Lege einen Schlägerkopfschutz 15 cm hinter den Ball. Mache Probeschwünge, bei denen du den Schutz knapp verfehlst – das erzwingt einen flacheren Angriff. Zu viel Spin entsteht durch einen steilen AoA; ein um 1,5° flacherer Angriff senkt den Spin um ca. 400–600 U/min und erhöht den Carry.',
  drillShallowTip: '"Streife das Gras, grabe nicht"',
  drillImpactTitle: 'Treffpunkt-Übung',
  drillImpactDesc: 'Sprühe Fußpuder oder klebe einen Aufprall-Sticker auf das Schlägerblatt. Schlage 10 Bälle und lies das Kontaktmuster ab. Ein Treffer außerhalb der Mitte kostet Weite – diese Übung macht das Problem sichtbar, damit du es beheben kannst.',
  drillImpactTip: '"Triff die Mitte, sichere die Yards"',
  drillGateTitle: 'Schlägerweg-Tor-Übung',
  drillGateDesc: 'Stecke zwei Tees je 2,5 cm breiter als dein Schlägerkopf in den Boden und bilde damit ein Tor. Schwinge durch, ohne ein Tee zu berühren. Das schult eine engere Schwungbahn und reduziert die Links-rechts-Streuung durch Schwungbahnfehler.',
  drillGateTip: '"Schläger durchs Tor, Ball auf die Linie"',
  drillShaftTitle: 'Vorwärtsneigung des Schafts beim Impact',
  drillShaftDesc: 'Stecke einen Schläger schräg mit Vorwärtsneigung hinter den Ball in den Boden. Übe Auftreffmomente, bei denen dein Griffende dem Winkel des Schlägers entspricht. Vorwärtsneigung de-loftet den Schläger und bringt Abflugwinkel und Spin in den optimalen Bereich.',
  drillShaftTip: '"Der Griff führt, folgt nicht"',
  drillTempoTitle: '3:1-Tempo-Übung',
  drillTempoDesc: 'Nutze eine Metronom-App bei 72 bpm. Der Rückschwung dauert 3 Schläge, der Abschwung 1. Inkonstantes Tempo ist der versteckte Treiber variablen Kontakts - ein gemessener Takt erzwingt jedes Mal die gleiche Auslieferung.',
  drillTempoTip: '"Langsam zurück, explosiv hindurch"',
  drillHalfTitle: 'Halbschwung-Kompressionsübung',
  drillHalfDesc: 'Mache Schwünge, die im Durchschwung auf Hüfthöhe stoppen. Konzentriere dich auf soliden Kontakt und das Gefühl, den Ball gegen den Boden zu pressen. Das baut die Gewohnheit konstanter Treffer auf, bevor du wieder Schwunglänge hinzunimmst.',
  drillHalfTip: '"Komprimieren, nicht casten"',
  drillLowFaceTitle: 'Korrektur des tiefen Schlagflächentreffers',
  drillLowFaceDesc: 'Tee den Driver so, dass mindestens die halbe Kugel über die Krone ragt. Übe das Streifen der Tee-Oberkante und verfolge Vertikalen Impact am Monitor, um einen Treffer von Mitte bis leicht hoch zu bestätigen. Tiefe Treffer fügen Backspin hinzu und töten den Abflug - ein Mitte-hoch-Kontakt kann den Spin um bis zu 1.000 U/min senken.',
  drillLowFaceTip: '"Hoch auf der Fläche, hoch im Ranking"',
  drillWallTitle: 'Wand-Übung - frühe Streckung stoppen',
  drillWallDesc: 'Stelle dich so auf, dass dein Hinterteil eine Wand oder einen festen Stuhl leicht berührt. Halte beim Rückschwung das hintere Gesäß an der Wand und spüre dann beim Impact, wie das vordere Gesäß den Wandkontakt übernimmt. Keine Wand? Nutze einen Stuhl hinter dir oder filme dich von der Seite, um den Hüftschub zu erkennen.',
  drillWallTip: '"Gesäß an die Wand, Haltung durch den Ball"',
  drillStepTitle: 'Durchschritt-Hüftübung',
  drillStepDesc: 'Schlage Eisen-Mittelschläge und lass deinen hinteren Fuß kurz nach dem Auftreffmoment Richtung Ziel treten – schließe ab, indem deine Gürtelschnalle über die Ziellinie zeigt. Blockierte Hüften erzwingen einen Handklapper, der den dynamischen Loft ansteigen lässt und Weite kostet – kontinuierliche Rotation beruhigt die Hände.',
  drillStepTip: '"Hüften öffnen, die Hände werden ruhig"',
  drillLagTitle: 'Pump-Übung - Lag aufbauen',
  drillLagDesc: 'Ziehe mit leichtem Griff den Griff, um den Abschwung zu starten, sodass der Schlägerkopf hinter den Händen zurückbleibt. Übe drei Pump-Bewegungen mit Stopp auf Hüfthöhe, der Schaft noch zum Ball geneigt, und schlage dann bei der vierten Wiederholung. Lag zu erhalten liefert einen Impact mit den Händen voran und entloftet den Schläger.',
  drillLagTip: '"Zieh den Griff, löse spät"',
  drillHeadcoverTitle: 'Schlägerhauben-Schlägerweg-Übung',
  drillHeadcoverDesc: 'Lege eine Schlägerhaube oder einen geneigten Ausrichtstab knapp außerhalb der Ziellinie und knapp hinter den Ball. Eine Over-the-top-Bewegung trifft ihn. Präge einen Abschwung ein, der den Schläger nach innen fallen lässt und ihn verfehlt. Ein Außen-innen-Weg mit offener Schlagfläche ist die Ursache des Slice - das Umleiten nach innen verkleinert Face-to-Path und flacht die Spin-Achse ab.',
  drillHeadcoverTip: '"Lass ihn innen fallen, schwinge nach rechts"',
  drillFaceCtrlTitle: 'Zwei-Knöchel-Schlagflächenkontrolle',
  drillFaceCtrlDesc: 'Prüfe, dass du im Stand zwei Knöchel deiner führenden Hand siehst. Schlage Halbschwünge und spüre, wie die Fläche durch den Impact zur Quadratur dreht, prüfe dann Abflugrichtung und Schlagfläche am Monitor. Die Fläche steuert beim Driver ~85% der Startrichtung - ein Grad Flächenwinkel entspricht 7–12 yd Abweichung auf Driver-Distanz.',
  drillFaceCtrlTip: '"Stelle die Fläche quadrat, starte auf Linie"',
  drillLowPointTitle: 'Tiefpunkt-Linien-Übung',
  drillLowPointDesc: 'Sprühe eine Kreidelinie auf den Rasen oder lege ein gefaltetes Handtuch 15 cm hinter den Ball. Trainiere deine Divots, auf der Zielseite der Linie zu beginnen. Halte beim Impact ~90% des Gewichts auf der vorderen Seite. Ein Tiefpunkt hinter dem Ball erzeugt fette und dünne Schläge; ihn nach vorn zu verlagern sichert jedes Mal Ball-zuerst-Kontakt.',
  drillLowPointTip: '"Ball zuerst, Rasen danach"',
  drillConnTitle: 'Verbindung - Handtuch unter den Armen',
  drillConnDesc: 'Klemme ein kleines Handtuch oder einen Handschuh unter die führende Achsel und mache Dreiviertelschwünge, wobei es durch den Impact eingeklemmt bleibt. Wenn sich die Arme vom Körper lösen, variieren Schwungebene und Flächenwinkel von Schlag zu Schlag - das Einklemmen zwingt Arme und Rotation, sich als eine Einheit zu bewegen.',
  drillConnTip: '"Arme und Brust, eine Bewegung"',
