  drillHalfTitle: 'Exercício de Compressão com Meio Swing',
  drillHalfDesc: 'Faça swings parando à altura da cintura no follow-through. Foque-se no contacto sólido e na sensação de prender a bola contra o chão. Isto constrói o hábito de consistência no golpe antes de reintroduzir o comprimento do swing.',
