  drillLowFaceTitle: 'Correção de Golpe na Parte Baixa da Face',
  drillLowFaceDesc: 'Coloque o driver no tee de forma a que pelo menos metade da bola fique acima da coroa. Pratique roçar o topo do tee e monitorize o Impacto Vertical no monitor para confirmar um golpe no centro a ligeiramente alto. Golpes baixos adicionam backspin e matam o lançamento - um contacto centro-alto pode baixar o spin até 1.000 rpm.',
  drillLowFaceTip: '"Alto na face, alto no leaderboard"',
  drillWallTitle: 'Exercício da Parede - Pare a Extensão Precoce',
  drillWallDesc: 'Posicione-se com a parte traseira a tocar levemente numa parede ou cadeira resistente. Faça swings mantendo o glúteo traseiro contra a parede no backswing, depois sinta o glúteo da frente assumir o contacto com a parede durante o impacto. Sem espaço para parede? Use uma cadeira atrás ou filme de lado para detetar o impulso dos quadris.',
  drillWallTip: '"Glúteos para a parede, postura pela bola"',
  drillStepTitle: 'Exercício de Passo com Rotação dos Quadris',
  drillStepDesc: 'Bata pancadas com ferro médio e deixe o pé traseiro avançar em direção ao alvo logo após o impacto, terminando com a fivela do cinto a apontar para além da linha de alvo. Ancas bloqueadas forçam uma viragem das mãos que eleva o loft dinâmico e custa distância - a rotação contínua sossega as mãos.',
