  drillLagTitle: 'Exercício de Bomba - Construir Lag',
  drillLagDesc: 'Com um grip leve, arraste o grip para iniciar o downswing de forma a que a cabeça do taco fique atrás das suas mãos. Pratique três movimentos de bomba parando à altura dos quadris com o shaft ainda inclinado para trás em direção à bola, depois bata na quarta repetição. Preservar o lag entrega um impacto com as mãos à frente e faz de-loft no taco.',
  drillLagTip: '"Arraste o grip, solte tarde"',
  drillHeadcoverTitle: 'Exercício da Capa de Caminho',
  drillHeadcoverDesc: 'Coloque uma capa de taco ou um alinhador em ângulo logo fora da linha do objetivo e logo atrás da bola. Um movimento over-the-top irá atingi-la. Groove um downswing que baixa o taco para o interior e a evita. O caminho out-to-in com a face aberta é a causa raiz do slice - redirecionar para o interior reduz a divergência face-caminho e achata o eixo de spin.',
