  drillFaceCtrlTitle: 'Controlo da Face com Dois Nós dos Dedos',
  drillFaceCtrlDesc: 'Verifique que vê dois nós dos dedos da mão da frente no address. Bata meio swings sentindo a face rodar para o quadrado no impacto, depois verifique Direção de Lançamento e Face do Taco no monitor. A face controla ~85% da direção de partida com o driver - um único grau de ângulo de face equivale a 7–12 jardas fora da linha à distância do driver.',
