  drillTempoDesc: 'Usa un’app metronomo a 72 bpm. Il backswing dura 3 battiti, il downswing 1. Il tempo inconsistente è il fattore nascosto del contatto variabile - un ritmo misurato forza la stessa erogazione ogni volta.',
