  drillHalfDesc: 'Esegui swing fermandoti all’altezza della vita nel follow-through. Concentrati su un contatto solido e sulla sensazione di intrappolare la palla contro il terreno. Questo costruisce l’abitudine alla consistenza di colpo prima di re-aggiungere la lunghezza dello swing.',
  drillHalfTip: '"Comprimi, non lanciare"',
  drillLowFaceTitle: 'Correzione del Colpo Basso sulla Faccia',
  drillLowFaceDesc: 'Posa il driver in modo che almeno metà della palla sia sopra la corona. Esercitati a sfiorare la sommità del tee e controlla l’Impatto Verticale sul monitor per confermare un colpo al centro o leggermente in alto. I colpi bassi aggiungono backspin e compromettono il lancio - un contatto centro-alto può ridurre lo spin fino a 1.000 rpm.',
  drillLowFaceTip: '"Alto sulla faccia, alto in classifica"',
  drillWallTitle: 'Esercizio al Muro - Stoppa l’Estensione Precoce',
  drillWallDesc: 'Mettiti in posizione con il gluteo posteriore leggermente a contatto con un muro o una sedia robusta. Esegui swing mantenendo il gluteo posteriore contro il muro nel backswing, poi senti il gluteo anteriore prendere contatto con il muro attraverso l’impatto. Niente muro? Usa una sedia dietro di te o registra di lato per individuare la spinta dell’anca.',
