  drillStepTip: '"Apri i fianchi, le mani si calmano"',
  drillLagTitle: 'Pump Drill - Costruisci il Lag',
  drillLagDesc: 'Con una presa leggera, trascina il manico per iniziare il downswing in modo che la testa della mazza rimanga indietro rispetto alle mani. Esercita tre movimenti di pompa fermandoti all’altezza dell’anca con il manico ancora inclinato verso la palla, poi colpisci al quarto ripetuto. Preservare il lag consegna un impatto con le mani in anticipo e riduce il loft.',
  drillLagTip: '"Trascina il manico, scatta tardi"',
  drillHeadcoverTitle: 'Esercizio del Percorso con Headcover',
  drillHeadcoverDesc: 'Posiziona una headcover o un bastone di allineamento angolato appena fuori dalla linea di gioco e appena dietro la palla. Un movimento over-the-top la colpirà. Consolida un downswing che porta la mazza all’interno evitandola. Il percorso fuori-dentro con faccia aperta è la causa principale dello slice - ridirigere verso l’interno riduce il gap faccia-percorso e appiattisce l’asse di spin.',
  drillHeadcoverTip: '"Dentro verso il basso, swing verso destra"',
  drillFaceCtrlTitle: 'Controllo della Faccia a Due Nocche',
  drillFaceCtrlDesc: 'Verifica di vedere due nocche della mano anteriore all’address. Esegui mezzi swing sentendo la faccia ruotare in quadratura attraverso l’impatto, poi controlla Direzione di Lancio e Faccia della Mazza sul monitor. La faccia controlla ~85% della direzione di partenza con il driver - un solo grado di angolo di faccia equivale a 7–12 yard fuori linea alla distanza del driver.',
  drillFaceCtrlTip: '"Quadra la faccia, partenza in linea"',
  drillLowPointTitle: 'Esercizio della Linea del Punto Basso',
