  insightLaunchHighDetail: '{deg}°는 {club}의 최적 {target}°를 초과합니다. 높은 스핀과 결합되면 볼루닝 탄도를 만듭니다. 임팩트 시 견고한 샤프트 린으로 런치를 낮추세요.',
  insightConsistHead: '샷 분산 ±{sd} {unit} - 거리보다 일관성 먼저',
