  drillShallowTitle: '어택 앵글 얕게 하기',
  drillShallowDesc: '볼 뒤 15cm 지점에 헤드커버를 놓으세요. 헤드커버를 피하는 연습 스윙을 반복합니다 - 이것이 얕은 어프로치를 강제합니다. 가파른 어택 앵글이 과다 스핀의 원인이며, 1.5° 얕게 하면 스핀이 약 400–600rpm 줄고 캐리가 늘어납니다.',
  drillShallowTip: '"잔디를 쓸되, 파지 마라"',
  drillImpactTitle: '임팩트 위치 드릴',
  drillImpactDesc: '클럽페이스에 풋 파우더 스프레이나 임팩트 스티커를 붙이세요. 볼 10개를 치고 컨택 패턴을 확인하세요. 페이스 중심을 벗어나면 거리 손실이 생깁니다 - 이 드릴이 문제를 눈에 보이게 만듭니다.',
  drillImpactTip: '"가운데를 쳐야 야드를 얻는다"',
  drillGateTitle: '패스 게이트 드릴',
  drillGateDesc: '클럽헤드 너비보다 2.5cm 넓게 티 두 개를 세워 패스 게이트를 만드세요. 어느 티도 건드리지 않고 스윙을 통과하세요. 이것이 스윙 패스를 좁히고 클럽 패스 오류로 인한 좌우 분산을 줄여줍니다.',
  drillGateTip: '"게이트를 통과해야 목표선이 살아난다"',
  drillShaftTitle: '임팩트 시 전방 샤프트 린',
  drillShaftDesc: '볼 앞쪽에서 포워드 기울기로 샤프트를 땅에 꽂으세요. 그립 끝이 샤프트 각도와 일치하는 임팩트를 연습하세요. 포워드 린이 클럽을 디로프트하여 런치각과 스핀을 최적 수준으로 맞춰줍니다.',
  drillShaftTip: '"핸들이 앞서야 한다"',
  drillTempoTitle: '3:1 템포 드릴',
  drillTempoDesc: '메트로놈 앱을 72 bpm으로 설정하세요. 백스윙은 3박자, 다운스윙은 1박자로 합니다. 불규칙한 템포는 가변적 타격의 숨은 원인입니다 - 일정한 박자가 매번 같은 딜리버리를 만들어냅니다.',
  drillTempoTip: '"천천히 올리고, 폭발적으로 치고"',
  drillHalfTitle: '하프 스윙 압축 드릴',
  drillHalfDesc: '팔로우스루에서 허리 높이에 멈추는 스윙을 합니다. 단단한 타격과 볼을 지면에 압축하는 느낌에 집중하세요. 스윙 길이를 늘리기 전에 타격 일관성 습관을 먼저 만드는 드릴입니다.',
  drillHalfTip: '"압축하라, 캐스팅하지 마라"',
  drillLowFaceTitle: '페이스 하단 타격 교정',
  drillLowFaceDesc: '볼의 절반 이상이 드라이버 크라운 위로 올라오도록 티를 꽂으세요. 티 상단을 스치는 연습을 하고 모니터에서 수직 임팩트를 확인해 중심~약간 상단 타격을 확인하세요. 하단 타격은 백스핀을 증가시키고 런치를 죽입니다 - 중심 상단 타격은 스핀을 최대 1,000 rpm 줄일 수 있습니다.',
  drillLowFaceTip: '"페이스 위로 쳐야 리더보드도 오른다"',
  drillWallTitle: '월 드릴 - 어얼리 익스텐션 방지',
  drillWallDesc: '뒷면이 벽이나 튼튼한 의자에 살짝 닿도록 어드레스하세요. 백스윙 시 트레일 둔부를 벽에 유지하고, 임팩트 시 리드 둔부가 벽을 이어받는 느낌을 익히세요. 공간이 없다면 뒤에 의자를 놓거나 측면 영상으로 힙 돌출을 확인하세요.',
  drillWallTip: '"둔부는 벽에, 자세는 볼을 통과해"',
  drillStepTitle: '스텝스루 힙 드릴',
  drillStepDesc: '미들 아이언 샷을 치면서 임팩트 직후 뒷발을 타겟 방향으로 스텝하고, 벨트 버클이 타겟 라인을 지나도록 피니시하세요. 힙이 멈추면 손이 뒤집히며 다이나믹 로프트가 급증해 거리 손실이 생깁니다 - 지속적인 회전이 손 동작을 안정시킵니다.',
  drillStepTip: '"힙을 클리어하면 손이 조용해진다"',
  drillLagTitle: '펌프 드릴 - 래그 만들기',
  drillLagDesc: '가볍게 그립하고 핸들을 끌어당기며 다운스윙을 시작해 클럽헤드가 손보다 뒤처지도록 하세요. 샤프트가 여전히 볼 쪽으로 기울어진 상태에서 힙 높이에서 멈추는 펌프 동작을 3회 반복한 후 네 번째에 샷을 치세요. 래그를 유지하면 핸즈 퍼스트 임팩트가 되어 클럽 로프트가 줄어듭니다.',
  drillLagTip: '"핸들을 끌고, 마지막에 폭발해"',
  drillHeadcoverTitle: '헤드커버 패스 드릴',
  drillHeadcoverDesc: '목표선 바로 바깥쪽 볼 바로 뒤에 헤드커버나 기울어진 얼라인먼트 스틱을 놓으세요. 오버더탑 동작은 이것을 건드립니다. 클럽을 인사이드로 내려오며 빗겨 가는 다운스윙을 익히세요. 오픈 페이스와 아웃투인 패스가 슬라이스의 근본 원인입니다 - 인사이드로 궤도를 바꾸면 페이스-패스 차이가 줄고 스핀 축이 수평해집니다.',
  drillHeadcoverTip: '"인사이드로 내려, 라이트 필드로 쳐라"',
  drillFaceCtrlTitle: '너클 두 개 페이스 컨트롤',
  drillFaceCtrlDesc: '어드레스 시 리드 손의 너클 두 개가 보이는지 확인하세요. 하프 스윙을 치며 임팩트 시 페이스가 스퀘어로 회전하는 느낌을 익히고, 모니터에서 런치 방향과 클럽 페이스를 확인하세요. 드라이버에서 페이스는 시작 방향의 약 85%를 결정합니다 - 페이스 각도 1도는 드라이버 거리에서 7–12 야드 오차를 만듭니다.',
  drillFaceCtrlTip: '"페이스를 스퀘어로, 목표선 위로 출발"',
  drillLowPointTitle: '로우 포인트 라인 드릴',
  drillLowPointDesc: '지면에 분필 선을 긋거나 볼 뒤 6인치에 접힌 수건을 놓으세요. 디봇이 목표 방향 쪽에서 시작되도록 훈련하세요. 임팩트 시 체중의 약 90%를 리드 사이드에 둡니다. 볼 뒤의 로우 포인트는 두꺼운 샷과 얇은 샷을 만듭니다 - 앞으로 이동시켜야 매번 볼 퍼스트 타격이 됩니다.',
  drillLowPointTip: '"볼 먼저, 잔디는 그 다음"',
  drillConnTitle: '연결 - 겨드랑이 수건 드릴',
  drillConnDesc: '리드 겨드랑이에 작은 수건이나 장갑을 끼우고 3/4 스윙을 하며 임팩트 시까지 고정되도록 하세요. 팔이 몸에서 분리되면 스윙 플레인과 페이스 각도가 샷마다 달라집니다 - 수건을 고정하면 팔과 회전이 하나의 유닛으로 움직이게 됩니다.',
