  insightAoaSteepDetail: '드라이버의 가파른 어택 앵글은 스핀 로프트를 넓히고 백스핀을 과도하게 증가시킵니다. −5°에서 +5°로 변경하면 동일한 클럽 속도에서 스핀이 약 1,100 rpm 줄고 최대 30 야드를 더할 수 있습니다. 어택 앵글을 얕게 하는 것이 드라이버에서 가장 레버리지가 높은 교정 포인트입니다.',
