const translations: Record<LangCode, TMap> = {
  en, es, fr, de, pt, it, nl, sv, ja, ko,
  'zh-hans': zhHans,
  'zh-hant': zhHant,
  th, no, da, fi,
};

export function t(lang: LangCode, key: TKey): string {
  return (translations[lang]?.[key] ?? translations.en[key]) as string;
}
